svg.script:
(function(){
  const CELL = 10;          // pixels per cell
  const DENSITY = 0.20;     // initial live-cell probability
  const FRAME_MS = 100;     // target frame time

  let svg, cellsG;
  let W=0, H=0;
  let grid = [];
  let running = true;
  let last = 0;

  function initGrid(w,h,d) {
    return Array.from({length:h}, () =>
      Array.from({length:w}, () => Math.random() < d)
    );
  }

  function neighbors(g, x, y) {
    let c=0;
    for (let dy=-1; dy<=1; dy++) for (let dx=-1; dx<=1; dx++) {
      if (dx||dy) if (g[(y+dy+H)%H][(x+dx+W)%W]) c++;
    }
    return c;
  }

  function step(g) {
    const n = Array.from({length:H}, () => Array(W).fill(false));
    for (let y=0; y<H; y++) for (let x=0; x<W; x++) {
      const nn = neighbors(g,x,y), a=g[y][x];
      n[y][x] = a ? (nn===2||nn===3) : (nn===3);
    }
    return n;
  }

  function draw(g) {
    let out = '';
    for (let y=0; y<H; y++) for (let x=0; x<W; x++)
      if (g[y][x]) out += `<rect class="alive" x="${x*CELL}" y="${y*CELL}" width="${CELL}" height="${CELL}"/>`;
    cellsG.innerHTML = out;
  }

  function resize() {
    const vbW = Math.floor(window.innerWidth  / CELL) * CELL;
    const vbH = Math.floor(window.innerHeight / CELL) * CELL;
    W = Math.floor(vbW / CELL);
    H = Math.floor(vbH / CELL);
    svg.setAttribute('viewBox', `0 0 ${vbW} ${vbH}`);
    grid = initGrid(W,H,DENSITY);
    draw(grid);
  }

  function loop(ts) {
    if (running && (ts - last >= FRAME_MS)) {
      grid = step(grid); draw(grid); last = ts;
    }
    requestAnimationFrame(loop);
  }

  function toggleAtClient(xClient, yClient) {
    const pt = svg.createSVGPoint();
    pt.x = xClient; pt.y = yClient;
    const global = pt.matrixTransform(svg.getScreenCTM().inverse());
    const x = Math.floor(global.x / CELL);
    const y = Math.floor(global.y / CELL);
    if (x>=0 && x<W && y>=0 && y<H) { grid[y][x] = !grid[y][x]; draw(grid); }
  }

  window.init = function(evt) {
    svg    = evt.target;
    cellsG = svg.getElementById('cells');

    svg.addEventListener('click', e => toggleAtClient(e.clientX, e.clientY));
    svg.addEventListener('keydown', e => {
      if (e.code === 'Space') { running = !running; e.preventDefault(); }
      else if (e.key === 'r') { grid = initGrid(W,H,DENSITY); draw(grid); }
    });
    window.addEventListener('resize', resize);

    svg.focus();
    resize();
    requestAnimationFrame(loop);
  };
})();
